st.markdown('''<div class="qqq-masthead">
  <div class="qqq-topline"><span>Vol. I · The magical edition</span><span>All the news that's fit to twist</span><span>Est. 2025</span></div>
  <div class="qqq-title">The Quick-Quotes Quill <span class="qqq-feather">❦</span></div>
  <div class="qqq-subtitle">A perfectly unreliable writing companion.</div>
</div>''', unsafe_allow_html=True)

st.markdown('<div class="qqq-input-title">✎ What happened?</div>', unsafe_allow_html=True)
source = st.text_area("Your statement", value="I missed the bus this morning and arrived late to school.", max_chars=1200, height=135, label_visibility="collapsed", key="source")
st.markdown('<div class="qqq-paper-note">Every ordinary story deserves a little drama. ✿</div>', unsafe_allow_html=True)

st.markdown('<div class="qqq-heading">✦ Choose your Quill ✦</div>', unsafe_allow_html=True)
if "mode" not in st.session_state:
    st.session_state.mode = "rita"
if "result" not in st.session_state:
    st.session_state.result = ""
if "result_mode" not in st.session_state:
    st.session_state.result_mode = "rita"

cols = st.columns(5, gap="small")
for col, (key, persona) in zip(cols, PERSONAS.items()):
    with col:
        with st.container(key=f"persona_{key}"):
            st.image(str(ASSETS / persona["image"]), use_container_width=True)
            if st.button(persona["name"], key=f"choose_{key}", use_container_width=True, type="primary" if st.session_state.mode == key else "secondary"):
                st.session_state.mode = key
                st.rerun()
            st.markdown(f'<div class="qqq-tagline">{html.escape(persona["tagline"])}</div>', unsafe_allow_html=True)

st.markdown('<div class="qqq-level">Drama Level</div>', unsafe_allow_html=True)
intensity = st.slider("Drama Level", 1, 5, 3, label_visibility="collapsed")

_, middle, _ = st.columns([1, 2, 1])
with middle:
    pressed = st.button("🪶 Let the Quill Write!", key="generate", type="primary", use_container_width=True)

if pressed:
    api_key = os.environ.get("GEMINI_API_KEY", "")
    try:
        api_key = api_key or st.secrets.get("GEMINI_API_KEY", "")
    except (FileNotFoundError, KeyError):
        pass
    if not source.strip():
        st.warning("Give the Quill a story first!")
    elif not api_key:
        st.error("Add GEMINI_API_KEY to .streamlit/secrets.toml first.")
    else:
        persona = PERSONAS[st.session_state.mode]
        instructions = f"""You are Quick-Quotes Quill, a charming creative rewriting toy.
SELECTED VOICE: {persona['name']}
VOICE GUIDE: {persona['guide']}
DRAMA INTENSITY: {intensity}/5.
INTENSITY GUIDE (more style, not more invented facts):
1: One light stylistic touch, close to original.
2: Restrained but recognizable voice.
3: Clear voice and one memorable device.
4: More audacious construction and two complementary devices.
5: Bold and hilarious or deeply expressive, with a memorable closing beat. Be vivid, not verbose.
RULES:
- Preserve all actual events, names, dates, numbers, outcomes, and stated uncertainty.
- A short input should normally yield 1–3 sentences, about 65 words at most. Faithful Drama should stay close to original length.
- Use personality-specific pacing, imagery and phrasing, not just adjectives.
- Rita can use tabloid headlines or mock-serious questions; no made-up evidence or allegations about real people.
- Faithful Drama must invent NOTHING. Make it natural, not wordy or robotic.
- Other personalities may use obviously figurative fiction but not claim new real-world facts, reactions or dialogue.
- Output only the rewritten text, plain text, no markdown, no quotation marks around the whole output.
"""
        with st.spinner("✒️ Ink, whispers, and a little magic…"):
            try:
                client = genai.Client(api_key=api_key)
                response = client.models.generate_content(
                    model="gemini-3.8-flash",  # Keep your currently working model; free-tier quotas apply.
                    contents=source.strip(),
                    config=types.GenerateContentConfig(system_instruction=instructions, max_output_tokens=2000, temperature=0.9),
                )
                if response.text:
                    st.session_state.result = response.text.strip().strip('`')
                    st.session_state.result_mode = st.session_state.mode
                else:
                    st.warning("The Quill returned an empty page. Try again.")
            except Exception as exc:
                msg = str(exc)
                if "429" in msg or "RESOURCE_EXHAUSTED" in msg:
                    st.warning("The Quill has run out of today's free ink! Your Gemini daily quota has been reached. Please try again after it resets.")
                else:
                    st.error(f"The Quill stumbled: {exc}")

if st.session_state.result:
    st.markdown('''<div class="qqq-result"><div class="qqq-result-head">The Quill Has Spoken</div><div class="qqq-result-eyebrow">✦ A DISPATCH FROM THE WRITING DESK ✦</div><div class="qqq-result-text">'''+html.escape(st.session_state.result)+'''</div></div>''', unsafe_allow_html=True)
    st.download_button("↓ Save this clipping", st.session_state.result, file_name="quick_quotes_quill.txt", mime="text/plain", use_container_width=True)


with st.expander("How the magic works (and what to believe)"):
    st.write("The Quill uses an AI model to rewrite your text in a fictional voice. Faithful Drama aims to preserve factual meaning; other voices may add obviously fictional flourishes. Check factual claims before sharing. The service has daily free-tier usage limits.")
